def pack_grid_field(field: GridField) -> PortableGrid:
    # Packing is a lossless serialization: the numerical content of the field
    # is carried over unchanged, and only the recorded length unit is
    # propagated.  Scaling densities by a volume factor (and weights by its
    # inverse) would silently change the physical meaning of the field,
    # because the screening workflow interprets the density threshold in
    # e/bohr^3 and evaluates length-dependent factors in bohr.
    return PortableGrid(
        density=np.asarray(field.values),
        cell_weights=np.asarray(field.weights),
        length_unit=field.length_unit,
    )


def unpack_grid_field(payload: PortableGrid) -> GridField:
    if payload.length_unit not in ("bohr", "angstrom"):
        raise ValueError(f"Unsupported portable grid unit: {payload.length_unit}")
    return GridField(
        values=np.asarray(payload.density),
        weights=np.asarray(payload.cell_weights),
        length_unit=payload.length_unit,
    )

