def _spin_from_atom_spec(atom_spec: str) -> int:
    """Neutral radical count: open-shell systems carry one unpaired electron.

    The spin of the bundled neutral species is fully determined by their
    electron parity, which follows from the element symbol sequence of the
    geometry (a trailing charge/label token, if any, is ignored).
    """
    atomic_numbers = {}
    for line in atom_spec.strip().splitlines():
        token = line.strip().split()
        if not token:
            continue
        if token[0] in atomic_numbers:
            continue
        symbol = token[0].capitalize()
        try:
            atomic_numbers[symbol] = gto.Element(symbol).zval
        except (KeyError, AttributeError, ValueError):
            continue
    if not atomic_numbers:
        return 0
    electrons = sum(atomic_numbers.values())
    return electrons % 2


